// Formats an Error Trigger item as "⚠️ <workflow> failed: <error>" for Telegram (HTML).
const e = $input.first().json;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const cut = (s, n) => (s.length <= n ? s : `${s.slice(0, n - 1)}…`);

const exec = e.execution || {};
const error = exec.error || (e.trigger && e.trigger.error) || {};
const workflow = (e.workflow && e.workflow.name) || 'A workflow';

const lines = [`⚠️ ${esc(workflow)} failed: ${esc(cut(String(error.message || 'unknown error'), 1500))}`];
if (exec.lastNodeExecuted) lines.push(`Node: ${esc(exec.lastNodeExecuted)}`);
if (exec.url) lines.push(`<a href="${esc(exec.url)}">Open execution</a>`);

return [{ json: { text: lines.join('\n') } }];
